/* WXT Shadow Root Reset */ :host{all:initial !important;}

  :host {
    all: initial !important;
    display: block !important;
    position: relative !important;
    width: 0 !important; height: 0 !important; overflow: visible !important;
    contain: none !important;
    color-scheme: light dark;
  }

  html,
  body {
    width: 0 !important;
    height: 0 !important;
    margin: 0 !important;
    padding: 0 !important;
    overflow: visible !important;
  }

  :host[data-fluent-read-viewport-ui="true"] {
    display: block !important;
    position: fixed !important;
    left: 0 !important;
    top: 0 !important;
    width: 100vw !important;
    height: 100vh !important;
    overflow: hidden !important;
    pointer-events: auto !important;
  }

  :host[data-fluent-read-viewport-ui="true"] > div {
    width: 100% !important;
    height: 100% !important;
    overflow: hidden !important;
  }

  :host([data-fluent-read-ui-suspended="true"]) {
    visibility: hidden !important;
    pointer-events: none !important;
  }

  *,
  *::before,
  *::after {
    box-sizing: border-box;
  }

